window.AgentBlazor = window.AgentBlazor || {
  version: "0.1.0-phase1",
  isLoaded: true,
  chat: {
    scrollToBottom: function (elementId) {
      var el = document.getElementById(elementId);
      if (el && typeof el.scrollTo === 'function') {
        el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
      }
    },
    attachEnterSubmit: function (textareaId, submitButtonId) {
      if (!textareaId || !submitButtonId) return;
      var textarea = document.getElementById(textareaId);
      if (!textarea) return;
      if (textarea._abChatEnterHandler) {
        textarea.removeEventListener('keydown', textarea._abChatEnterHandler);
        textarea._abChatEnterHandler = null;
      }
      var submitBtn = document.getElementById(submitButtonId);
      if (!submitBtn) return;
      var handler = function (e) {
        if ((e.key === 'Enter' || e.key === 'NumpadEnter') && !e.shiftKey) {
          e.preventDefault();
          submitBtn.click();
        }
      };
      textarea.addEventListener('keydown', handler);
      textarea._abChatEnterHandler = handler;
    },
    detachEnterSubmit: function (textareaId) {
      var textarea = document.getElementById(textareaId);
      if (textarea && textarea._abChatEnterHandler) {
        textarea.removeEventListener('keydown', textarea._abChatEnterHandler);
        textarea._abChatEnterHandler = null;
      }
    },
    setInputValue: function (elementId, value) {
      var input = document.getElementById(elementId);
      if (!input) return;
      input.value = value || '';
      input.dispatchEvent(new Event('input', { bubbles: true }));
    },
    getInputValue: function (elementId) {
      var input = document.getElementById(elementId);
      return input ? input.value || '' : '';
    }
  },
  markdown: {
    _mermaidModule: null,
    _highlightModule: null,

    // Enhances a rendered markdown container: renders mermaid/nomnoml
    // diagrams and syntax-highlights fenced code blocks. Idempotent via a
    // content-hash guard (data-ab-processed), so Blazor re-diffs, hydration,
    // and parent re-renders never double-render. Returns a Promise so the
    // caller can re-request scrollToBottom after layout settles.
    enhance: function (containerEl, options) {
      options = options || {};
      return new Promise(function (resolve) {
        if (!containerEl || typeof containerEl.querySelector !== 'function') {
          resolve(false);
          return;
        }

        // Content-hash guard: same source → no re-enhance. The caller (Blazor
        // component) passes a stable sourceHash computed from the markdown
        // source BEFORE rendering, because after enhancement the DOM is
        // mutated (SVG + hljs spans) and textContent-based hashing would
        // mismatch on every subsequent call.
        var sourceHash = options.sourceHash || AgentBlazor.markdown._hash(containerEl.textContent || '');
        if (containerEl.getAttribute('data-ab-processed') === sourceHash) {
          resolve(false);
          return;
        }
        containerEl.setAttribute('data-ab-processed', sourceHash);

        var theme = AgentBlazor.markdown._themeFrom(containerEl);
        var work = [];

        if (options.enableMermaid !== false) {
          var diagramNodes = containerEl.querySelectorAll('.mermaid, .nomnoml');
          if (diagramNodes.length) {
            work.push(AgentBlazor.markdown._renderDiagrams(diagramNodes, theme, options));
          }
        }

        if (options.enableSyntaxHighlighting !== false) {
          var codeBlocks = containerEl.querySelectorAll('pre code[class*="language-"]');
          if (codeBlocks.length) {
            work.push(AgentBlazor.markdown._highlight(codeBlocks, options));
          }
        }

        Promise.all(work).then(function (results) {
          resolve(results.some(function (r) { return r; }));
        }).catch(function () {
          resolve(false);
        });
      });
    },

    // djb2 hash of the container text — cheap, stable, collision-safe enough
    // for the idempotency guard.
    _hash: function (str) {
      var h = 5381;
      for (var i = 0; i < str.length; i++) {
        h = ((h << 5) + h + str.charCodeAt(i)) | 0;
      }
      return (h >>> 0).toString(36);
    },

    _themeFrom: function (el) {
      var node = el;
      while (node && node.getAttribute) {
        var theme = node.getAttribute('data-theme');
        if (theme) return theme;
        node = node.parentElement;
      }
      return 'default';
    },

    _mermaidTheme: function (theme) {
      // data-theme values on the chat surface: "light"/"dark" (or "default").
      return theme === 'dark' ? 'dark' : 'default';
    },

    _renderDiagrams: function (nodes, theme, options) {
      return AgentBlazor.markdown._loadMermaid(options).then(function (mermaid) {
        mermaid.initialize({
          startOnLoad: false,
          theme: AgentBlazor.markdown._mermaidTheme(theme),
          securityLevel: 'strict',
          suppressErrorRendering: true
        });
        var renders = Array.prototype.map.call(nodes, function (node) {
          return mermaid.render('ab-md-' + Math.random().toString(36).slice(2, 10), node.textContent || '')
            .then(function (res) {
              node.innerHTML = res.svg || '';
              var svgEl = node.querySelector('svg');
              if (svgEl) {
                svgEl.setAttribute('role', 'img');
                svgEl.setAttribute('aria-label', AgentBlazor.markdown._diagramLabel(node));
              }
              return true;
            })
            .catch(function () {
              // suppressErrors: leave the raw source text visible as fallback.
              return false;
            });
        });
        return Promise.all(renders).then(function (results) {
          return results.some(function (r) { return r; });
        });
      }).catch(function () {
        return false;
      });
    },

    _diagramLabel: function (node) {
      var kind = 'diagram';
      if (node.className) {
        var match = String(node.className).match(/mermaid|nomnoml/);
        if (match) kind = match[0];
      }
      return 'Diagram: ' + kind;
    },

    _highlight: function (codeBlocks, options) {
      return AgentBlazor.markdown._loadHighlight(options).then(function (hljs) {
        var highlighted = 0;
        Array.prototype.forEach.call(codeBlocks, function (codeEl) {
          try {
            hljs.highlightElement(codeEl);
            highlighted++;
          } catch (e) { /* keep unhighlighted */ }
        });
        return highlighted > 0;
      }).catch(function () {
        return false;
      });
    },

    // Lazy script-tag loaders for UMD CDN builds. Dynamic import() was
    // evaluated and rejected: highlight.js v11 ships only Node CJS (lib/*)
    // and a broken-for-browsers ESM (es/* re-exports the CJS build, which the
    // browser cannot interop), so a script tag + global is the only reliable
    // path. Both URLs verified: cdnjs highlight.min.js (UMD, all languages)
    // and jsdelivr mermaid dist/mermaid.min.js (UMD, sets window.mermaid).
    _loadMermaid: function (options) {
      return AgentBlazor.markdown._loadScript(
        options.mermaidScriptUrl || 'https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js',
        'window.mermaid');
    },

    _loadHighlight: function (options) {
      return AgentBlazor.markdown._loadScript(
        options.highlightScriptUrl || 'https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.11.1/highlight.min.js',
        'window.hljs');
    },

    _loadScript: function (url, globalPath) {
      var self = AgentBlazor.markdown;
      if (self._loadedScripts === undefined) {
        self._loadedScripts = {};
      }
      if (self._loadedScripts[url]) {
        return Promise.resolve(self._loadedScripts[url]);
      }
      return new Promise(function (resolve, reject) {
        var script = document.createElement('script');
        script.src = url;
        script.async = true;
        script.onload = function () {
          var value = self._globalValue(globalPath);
          if (value) {
            self._loadedScripts[url] = value;
            resolve(value);
          } else {
            reject(new Error('Script loaded but global not found: ' + globalPath));
          }
        };
        script.onerror = function () {
          reject(new Error('Failed to load script: ' + url));
        };
        document.head.appendChild(script);
      });
    },

    _globalValue: function (path) {
      var parts = path.split('.');
      var value = window;
      for (var i = 0; i < parts.length; i++) {
        if (!value) return null;
        value = value[parts[i]];
      }
      return value || null;
    }
  },
  internal: {
    _frontendActions: {},
    _sharedState: {},
    _eventListeners: {},
    _suggestions: [],
    
    capturePageStructure: function () {
      var components = [];
      var knownComponents = ['agent-datagrid', 'agent-dialog', 'agent-form', 'agent-tabs', 'agent-nav-menu', 'agent-select'];
      var knownPrefixes = ['agentdatagrid', 'agentdialog', 'agentform', 'agenttabs', 'agentnavmenu', 'agentselect'];
      
      function getComponentInfo(el) {
        var id = el.id || '';
        var classes = el.className || '';
        var dataAttrs = {};
        
        for (var i = 0; i < el.attributes.length; i++) {
          var attr = el.attributes[i];
          if (attr.name.startsWith('data-ab-')) {
            dataAttrs[attr.name] = attr.value;
          }
        }
        
        var type = '';
        for (var j = 0; j < knownPrefixes.length; j++) {
          if (id.toLowerCase().startsWith(knownPrefixes[j]) || (typeof classes === 'string' && classes.toLowerCase().includes(knownPrefixes[j]))) {
            type = knownComponents[j].replace('agent-', '').replace('-', '');
            break;
          }
        }
        
        if (!type && el.tagName) {
          type = el.tagName.toLowerCase();
        }
        
        return {
          id: id,
          type: type,
          tagName: el.tagName ? el.tagName.toLowerCase() : '',
          classes: typeof classes === 'string' ? classes.split(' ').filter(function(c) { return c; }) : [],
          dataAttributes: dataAttrs,
          childCount: el.children ? el.children.length : 0
        };
      }
      
      function walkTree(el, depth) {
        if (depth > 10) return;
        
        var info = getComponentInfo(el);
        if (info.type && info.type !== el.tagName) {
          components.push(info);
        }
        
        if (el.children) {
          for (var i = 0; i < el.children.length; i++) {
            walkTree(el.children[i], depth + 1);
          }
        }
      }
      
      walkTree(document.body, 0);
      
      return {
        url: window.location.pathname,
        timestamp: new Date().toISOString(),
        components: components
      };
    },
    
    registerFrontendAction: function (name, handler) {
      this._frontendActions[name] = handler;
    },
    
    unregisterFrontendAction: function (name) {
      delete this._frontendActions[name];
    },
    
    executeFrontendAction: function (name, args) {
      var action = this._frontendActions[name];
      if (typeof action === 'function') {
        try {
          var result = action(args);
          return { success: true, result: result };
        } catch (e) {
          return { success: false, error: e.message };
        }
      }
      return { success: false, error: 'Action not found: ' + name };
    },
    
    getFrontendActions: function () {
      return Object.keys(this._frontendActions);
    },
    
    setSharedState: function (key, value) {
      this._sharedState[key] = value;
      this._emit('stateChanged', { key: key, value: value });
    },
    
    getSharedState: function (key) {
      return key ? this._sharedState[key] : this._sharedState;
    },
    
    getAllSharedState: function () {
      return JSON.parse(JSON.stringify(this._sharedState));
    },
    
    clearSharedState: function () {
      this._sharedState = {};
      this._emit('stateChanged', { key: null, value: null });
    },
    
    addEventListener: function (event, callback) {
      if (!this._eventListeners[event]) {
        this._eventListeners[event] = [];
      }
      this._eventListeners[event].push(callback);
    },
    
    removeEventListener: function (event, callback) {
      if (this._eventListeners[event]) {
        var idx = this._eventListeners[event].indexOf(callback);
        if (idx > -1) {
          this._eventListeners[event].splice(idx, 1);
        }
      }
    },
    
    _emit: function (event, data) {
      if (this._eventListeners[event]) {
        this._eventListeners[event].forEach(function(cb) {
          try { cb(data); } catch (e) {}
        });
      }
    },
    
    emitAgentEvent: function (eventType, data) {
      this._emit('agent:' + eventType, data);
    },
    
    setSuggestions: function (suggestions) {
      this._suggestions = suggestions || [];
      this._emit('suggestionsChanged', this._suggestions);
    },
    
    getSuggestions: function () {
      return this._suggestions.slice();
    },
    
    clearSuggestions: function () {
      this._suggestions = [];
      this._emit('suggestionsChanged', []);
    },
    
    getViewportInfo: function () {
      return {
        width: window.innerWidth,
        height: window.innerHeight,
        scrollX: window.scrollX,
        scrollY: window.scrollY,
        devicePixelRatio: window.devicePixelRatio
      };
    },
    
    getActiveElement: function () {
      var el = document.activeElement;
      if (!el) return null;
      return {
        tagName: el.tagName,
        id: el.id,
        className: el.className,
        value: el.value,
        type: el.type
      };
    }
  }
};
